def solution():
    # Define the strings
    S = "es"
    T = "bc"

    # Initialize a 2D array to store lengths of LCS
    m = len(S)
    n = len(T)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp array in a bottom-up manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif S[i - 1] == T[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of LCS is stored in dp[m][n]
    return dp[m][n]

