def solution():
    # Given parameters
    W = np.array([9, 5])  # Weights
    V = np.array([17, 8])  # Values
    C = 2  # Capacity

    # Initialize a table to store results of subproblems
    dp = np.zeros((len(W) + 1, C + 1))

    # Fill dp[][] in bottom up manner
    for i in range(len(W) + 1):
        for w in range(C + 1):
            if i == 0 or w == 0:
                dp[i][w] = 0
            elif W[i-1] <= w:
                dp[i][w] = max(V[i-1] + dp[i-1][w-W[i-1]],  dp[i-1][w])
            else:
                dp[i][w] = dp[i-1][w]

    return int(dp[len(W)][C])

